import {CatalogPage,DocumentEditor,ProcessPanel,ExtraFields,UniversalReadings,EventGrid} from "./universal-ui";
import React,{useState,useEffect,useRef,useCallback,createContext,useContext} from "react";
import {LayoutDashboard,FileText,Files,ClipboardCheck,GitBranch,RotateCcw,Stamp,Eye,Archive,Users,Search,Bell,ChevronDown,ChevronRight,ChevronLeft,Plus,ArrowUpRight,ArrowRight,ArrowLeft,Clock,CalendarDays,Check,CheckCheck,MessageSquare,Paperclip,Download,Upload,MoreHorizontal,SlidersHorizontal,X,Building2,HelpCircle,FilePlus2,FileCheck2,Send,Printer,Link as LinkIcon,RefreshCw,ArrowDownUp,AlertCircle,BookOpen,FolderOpen,Loader2,BriefcaseBusiness,PanelLeftClose} from "lucide-react";
