type Session={systemRole?:string;username:string;actor:string;canSwitch:boolean};
type ApiResult={receipt?:{username:string;password:string};session?:Session;state:SedState;revision:number;error?:string};
type Modal={taskId?:string;kind:string;documentId?:string;readingId?:string;type?:string};
type AppContext={session:Session|null;data:SedState;actor:string;busy:boolean;go:(v:string,id?:string)=>void;open:(m:Modal)=>void;act:(action:string,p?:Record<string,unknown>)=>Promise<SedState|null>;upload:(f:File,docId:string,groupId?:string,options?:{purpose?:string;comment?:string})=>Promise<void>};
export const Context=createContext<AppContext>(null!);
export const useApp=()=>useContext(Context);
function Avatar({id,small=false}:{id:string;small?:boolean}){const p=person(id);return <span title={p.name+" · "+p.department} className={`avatar ${p.color} ${small?"small":""}`}>{p.initials}</span>}
function Status({value}:{value:string}){return <span className={`status ${value}`}><span/>{statusLabels[value]||value}</span>}
function Blank({title="Пока ничего нет",description="Новые документы появятся здесь."}:{title?:string;description?:string}){return <Empty><EmptyHeader><EmptyMedia variant="icon"><FolderOpen/></EmptyMedia><EmptyTitle>{title}</EmptyTitle><EmptyDescription>{description}</EmptyDescription></EmptyHeader></Empty>}
export function Pick({value,onChange,items,label}:{value:string;onChange:(s:string)=>void;items:Record<string,string>;label:string}){return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className="pick"><SelectValue/></SelectTrigger><SelectContent>{Object.entries(items).map(([k,v])=><SelectItem key={k} value={k}>{v}</SelectItem>)}</SelectContent></Select>}
const roleItems=()=>Object.fromEntries(people.filter(p=>p.active!==false).map(p=>[p.id,p.name+" · "+p.department]));
const titles:Record<string,string>={types:"Типы документов",processes:"Шаблоны процессов",cases:"Дела и сроки хранения",users:"Пользователи",templates:"Шаблоны маршрутов",home:"Рабочий стол",documents:"Все документы",contracts:"Договоры",tasks:"Мои задачи",review:"На согласовании",revision:"На доработке",approval:"На утверждении",readings:"Ознакомление",archive:"Архив",directory:"Справочники",active:"Документы в работе",completed:"Завершённые документы",overdue:"Контроль сроков",notifications:"Уведомления",doc:"Документ"};

export default function Workspace(){
 const [receipt,setReceipt]=useState<{username:string;password:string}|null>(null);
 const [session,setSession]=useState<Session|null>(null);
 const [data,setData]=useState<SedState|null>(null),[revision,setRevision]=useState(0),[error,setError]=useState(""),[actor,setActor]=useState("secretary"),[view,setView]=useState("home"),[docId,setDocId]=useState(""),[search,setSearch]=useState(""),[busy,setBusy]=useState(false),[modal,setModal]=useState<Modal|null>(null),[notifications,setNotifications]=useState(false);
 const dataRef=useRef(data),revRef=useRef(revision),actorRef=useRef(actor);dataRef.current=data;revRef.current=revision;actorRef.current=actor;const lock=useRef(false);
 const apply=useCallback((r:ApiResult)=>{if(r.state.people)setPeople(r.state.people);if(r.state.documentTypes)setTypes(r.state.documentTypes);if(r.receipt)setReceipt(r.receipt);if(r.session){setSession(r.session);if(!r.session.canSwitch||!people.some(p=>p.id===actorRef.current&&p.active!==false)){setActor(r.session.actor);actorRef.current=r.session.actor;}}setData(r.state);setRevision(r.revision);dataRef.current=r.state;revRef.current=r.revision;setError("");},[]);
 const reload=useCallback(async()=>{try{const r=await fetch("/api/sed",{cache:"no-store"});if(r.status===401){location.href="/login";return;}const json=await r.json() as ApiResult;if(!r.ok)throw new Error(json.error);apply(json);}catch(e){setError(e instanceof Error?e.message:"Не удалось загрузить данные");}},[apply]);
 const go=useCallback((v:string,id?:string)=>{setView(v);setDocId(id||"");setSearch("");const p=new URLSearchParams();if(v!=="home")p.set("view",v);if(id)p.set("id",id);history.pushState(null,"",p.size?"?"+p.toString():"/");window.scrollTo(0,0);},[]);
 useEffect(()=>{const restore=()=>{const p=new URLSearchParams(location.search);setView(titles[p.get("view")||""]?p.get("view")!:"home");setDocId(p.get("id")||"");};restore();const preferred=localStorage.getItem("resminama-actor");if(people.some(p=>p.id===preferred))setActor(preferred!);reload();window.addEventListener("popstate",restore);return()=>window.removeEventListener("popstate",restore);},[reload]);
 const act=useCallback(async(action:string,p:Record<string,unknown>={})=>{if(lock.current)return null;lock.current=true;setBusy(true);try{const r=await fetch("/api/sed",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,actor:actorRef.current,revision:revRef.current,...p})});const json=await r.json() as ApiResult;if(!r.ok){if(r.status===401){location.href="/login";return null;}if(r.status===409)await reload();throw new Error(json.error);}apply(json);if(action!=="readEvents")toast.success("Изменения сохранены");return json.state as SedState;}catch(e){toast.error(e instanceof Error?e.message:"Не удалось сохранить");return null;}finally{lock.current=false;setBusy(false);}},[apply,reload]);
 async function upload(file:File,documentId:string,groupId?:string,options?:{purpose?:string;comment?:string}){if(lock.current)return;lock.current=true;setBusy(true);try{const f=new FormData();f.set("file",file);f.set("documentId",documentId);f.set("actor",actorRef.current);f.set("revision",String(revRef.current));if(options?.purpose)f.set("purpose",options.purpose);if(options?.comment)f.set("comment",options.comment);const prior=options?.purpose==="process"?undefined:dataRef.current?.attachments.find(a=>a.documentId===documentId&&(groupId?a.groupId===groupId:a.name===file.name));if(prior){f.set("groupId",prior.groupId);const lease=dataRef.current?.fileLocks?.find(l=>l.groupId===prior.groupId&&l.username===session?.username);f.set("baseVersion",String(lease?.baseVersion??Math.max(...(dataRef.current?.attachments.filter(a=>a.groupId===prior.groupId).map(a=>a.version)||[0]))));}const r=await fetch("/api/files",{method:"POST",body:f});const j=await r.json() as ApiResult;if(!r.ok){if(r.status===409)await reload();throw new Error(j.error);}apply(j);toast.success("Файл загружен, версия сохранена");}catch(e){toast.error(e instanceof Error?e.message:"Ошибка загрузки");}finally{setBusy(false);lock.current=false;}}
 useEffect(()=>{const ctx=(document as unknown as {modelContext?:{registerTool:(tool:unknown,opts:unknown)=>Promise<void>|void}}).modelContext;if(!ctx?.registerTool)return;const controller=new AbortController();for(const tool of [
  {name:"search_documents",description:"Find RESMINAMA documents by title, registration number, or correspondent.",inputSchema:{type:"object",properties:{query:{type:"string"}},required:["query"],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input:unknown){const p=input as {query:string};if(typeof p?.query!=="string")throw new Error("query must be a string");return {documents:(dataRef.current?.documents||[]).filter(d=>(d.title+" "+d.number+" "+d.correspondent).toLowerCase().includes(p.query.toLowerCase())).map(d=>({id:d.id,title:d.title,number:d.number,status:statusLabels[d.status]}))};}},
  {name:"open_document",description:"Open an existing RESMINAMA document card. Does not change the document.",inputSchema:{type:"object",properties:{id:{type:"string"}},required:["id"],additionalProperties:false},annotations:{readOnlyHint:true},execute(input:unknown){const p=input as {id:string};const d=dataRef.current?.documents.find(d=>d.id===p?.id);if(!d)throw new Error("Document not found");go("doc",d.id);return {id:d.id,title:d.title};}}
 ]){try{Promise.resolve(ctx.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}return()=>controller.abort();},[go]);
 const current=data?.documents.find(d=>d.id===docId);const unread=data?.events.filter(e=>!data.readEvents.includes(e.id)).length||0;
 return <SidebarProvider style={{"--sidebar-width":"244px"} as React.CSSProperties}><Toaster position="bottom-right" theme="light" richColors/><Context.Provider value={{session,data:data||{documents:[],events:[],tasks:[],attachments:[],readEvents:[],readings:[]},actor,busy,go,open:setModal,act,upload}}>
 <Navigation view={view}/><div className="workspace-main"><header className="topbar"><div className="topbar-start"><SidebarTrigger aria-label="Свернуть или открыть меню"/><span className="topbar-location">Рабочее пространство<ChevronRight size={14}/><b>{current?.number||titles[view]}</b></span></div><form className="global-search" onSubmit={e=>{e.preventDefault();setView("documents");setDocId("");history.pushState(null,"","?view=documents");}}><Search size={17}/><input aria-label="Поиск по документам" placeholder="Найти документ…" value={search} onChange={e=>{setSearch(e.target.value);if(e.target.value){setView("documents");setDocId("");}}}/><kbd>⌕</kbd></form><div className="topbar-tools"><button className="icon-button" aria-label="Обновить данные" title="Обновить данные" disabled={busy} onClick={reload}><RefreshCw size={18}/></button><DropdownMenu open={notifications} onOpenChange={setNotifications}><DropdownMenuTrigger asChild><button className="icon-button notification-button" aria-label="Уведомления"><Bell size={20}/>{unread>0&&<i/>}</button></DropdownMenuTrigger><DropdownMenuContent align="end" className="notification-menu"><div className="notification-heading"><b>Уведомления</b><span>{unread} новых</span></div>{data?.events.slice(0,5).map(e=><DropdownMenuItem key={e.id} className="notification-item" onSelect={()=>{go("doc",e.documentId);setNotifications(false);}}><Avatar id={e.actor} small/><div><b>{e.action}</b><p>{data.documents.find(d=>d.id===e.documentId)?.title||e.comment}</p></div></DropdownMenuItem>)}<DropdownMenuSeparator/><DropdownMenuItem onSelect={()=>act("readEvents")}><CheckCheck size={16}/>Отметить всё прочитанным</DropdownMenuItem></DropdownMenuContent></DropdownMenu><span className="topbar-divider"/><DropdownMenu><DropdownMenuTrigger asChild><button className="profile-button"><Avatar id={actor}/><span><b>{person(actor).name}</b><small>{person(actor).role}{session?.canSwitch?" · администратор":""}</small></span><ChevronDown size={15}/></button></DropdownMenuTrigger><DropdownMenuContent align="end" className="profile-menu"><DropdownMenuLabel>{session?.canSwitch?"Администратор: выбрать роль":"Моя учётная запись"}</DropdownMenuLabel><DropdownMenuSeparator/>{people.filter(p=>p.active!==false&&(!session||session.canSwitch||p.id===session.actor)).map(p=><DropdownMenuItem key={p.id} onSelect={()=>{setActor(p.id);localStorage.setItem("resminama-actor",p.id);toast.info("Вы работаете как "+p.name);}}><Avatar id={p.id} small/><div><b>{p.name}</b><small>{p.department}</small></div>{actor===p.id&&<Check size={16}/>}</DropdownMenuItem>)}{session&&<><DropdownMenuSeparator/><DropdownMenuItem onSelect={()=>location.href="/account"}>Сменить пароль</DropdownMenuItem><DropdownMenuItem onSelect={async()=>{await fetch("/api/logout",{method:"POST"});location.href="/login";}}>Выйти</DropdownMenuItem></>}</DropdownMenuContent></DropdownMenu></div></header>
 <main className="page-content">{error?<section className="panel error-panel"><AlertCircle/><h1>Не удалось загрузить пространство</h1><p>{error}</p><button className="btn primary" onClick={reload}><RefreshCw size={16}/>Повторить</button></section>:!data?<div className="loading-layout"><Skeleton className="h-10 w-72"/><div className="stats-grid">{[1,2,3,4].map(x=><Skeleton key={x} className="h-32 rounded-xl"/>)}</div><Skeleton className="h-96 rounded-xl"/></div>:view==="home"?<Dashboard/>:view==="doc"?(current?<DocumentDetail key={current.id} doc={current}/>:<Blank title="Документ не найден" description="Вернитесь к списку документов."/>):view==="tasks"?<TasksPage/>:view==="readings"?<ReadingsPage/>:view==="directory"?<Directory/>:view==="users"?<UsersPage/>:view==="types"?<CatalogPage kind="types"/>:view==="processes"?<CatalogPage kind="processes"/>:view==="templates"?<TemplatesPage/>:view==="cases"?<CasesPage/>:view==="archive"?<ArchivePage/>:<DocumentsPage view={view} search={search} setSearch={setSearch}/>}</main><footer className="page-footer"><span>RESMINAMA <span className="footer-dot">·</span> Электронный документооборот</span><span>Локальная СЭД · v0.3.0 · сборка 3</span></footer></div>
 {receipt&&<Dialog open onOpenChange={v=>!v&&setReceipt(null)}><DialogContent className="app-dialog"><DialogHeader><DialogTitle>Пароль пользователя</DialogTitle><DialogDescription>Сохраните пароль и передайте сотруднику. Повторно он не показывается.</DialogDescription></DialogHeader><div className="credential-box"><span>Логин</span><b>{receipt.username}</b><span>Новый пароль</span><code>{receipt.password}</code></div><p className="muted">После входа сотрудник может сменить пароль в меню профиля.</p><DialogFooter><button className="btn primary" onClick={()=>setReceipt(null)}>Сохранил, закрыть</button></DialogFooter></DialogContent></Dialog>}
 {modal&&(["create","edit"].includes(modal.kind)?<DocumentEditor key={modal.kind+modal.documentId} modal={modal} close={()=>setModal(null)}/>:modal.kind==="taskDetail"?<TaskDialog taskId={modal.taskId!} close={()=>setModal(null)}/>:modal.kind==="archive"||modal.kind==="restore"?<ArchiveDialog modal={modal} close={()=>setModal(null)}/>:<ModalFlow key={modal.kind+modal.documentId+modal.readingId} modal={modal} close={()=>setModal(null)}/>)}</Context.Provider></SidebarProvider>;
}

function Navigation({view}:{view:string}){const {data,actor,go,open,session}=useApp();const {setOpenMobile}=useSidebar();const count=(s:string)=>data.documents.filter(d=>d.status===s).length;const readingCount=data.readings.filter(r=>r.recipients.includes(actor)&&!r.done.includes(actor)).length+data.documents.filter(d=>currentStep(d)?.kind==="acknowledge"&&currentStep(d)?.participants.includes(actor)&&!currentStep(d)?.decisions?.[actor]).length;const items=[{label:"Рабочее пространство",links:[["home","Рабочий стол",LayoutDashboard,0],["tasks","Мои задачи",ClipboardCheck,data.tasks.filter(t=>t.assignee===actor&&!taskClosed(t)).length]]},{label:"Документы",links:[["documents","Все документы",Files,0],["contracts","Договоры",BriefcaseBusiness,0],["review","Согласование",GitBranch,count("review")],["revision","Доработка",RotateCcw,count("revision")],["approval","Утверждение",Stamp,count("approval")],["readings","Ознакомление",Eye,readingCount]]},{label:"Организация",links:[["archive","Архив",Archive,0],["cases","Дела",FolderOpen,0],["directory","Справочники",Users,0],["types","Типы документов",Files,0],["processes","Процессы",GitBranch,0],["templates","Согласование v0.2",GitBranch,0],...(session?.canSwitch?[["users","Пользователи",Users,0]]:[]) ]}];return <Sidebar className="app-sidebar" collapsible="offcanvas"><SidebarHeader className="brand-header"><button onClick={()=>{go("home");setOpenMobile(false);}} className="brand"><span className="brand-mark"><Files size={25}/></span><span>RESMINAMA<small>ДОКУМЕНТООБОРОТ</small></span></button></SidebarHeader><SidebarContent className="nav-content">{items.map(section=><SidebarGroup key={section.label}><SidebarGroupLabel className="nav-label">{section.label}</SidebarGroupLabel><SidebarMenu>{section.links.map(([id,label,Icon,n])=>{const I=Icon as typeof Files;return <SidebarMenuItem key={String(id)}><SidebarMenuButton className="nav-button" isActive={view===id} onClick={()=>{go(id as string);setOpenMobile(false);}}><I size={19}/><span>{label as string}</span>{!!n&&<em className={id==="revision"?"amber-count":""}>{n as number}</em>}</SidebarMenuButton></SidebarMenuItem>})}</SidebarMenu></SidebarGroup>)}</SidebarContent><SidebarFooter className="nav-footer"><button className="demo-info" onClick={()=>open({kind:"help"})}><span className="demo-icon"><BookOpen size={20}/></span><span><b>Знакомство с RESMINAMA</b><small>Как устроена работа</small></span><ArrowUpRight size={17}/></button><div className="nav-bottom"><span className="workspace-icon"><Building2 size={19}/></span><span><b>Моя организация</b><small>Локальная СЭД</small></span><button className="icon-button" aria-label="Справка" onClick={()=>open({kind:"help"})}><HelpCircle size={17}/></button></div></SidebarFooter></Sidebar>}

function PageHead({title,subtitle,children}:{title:string;subtitle?:string;children?:React.ReactNode}){return <div className="page-heading"><div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div><div className="heading-actions">{children}</div></div>}
function Dashboard(){const {data,actor,go,open}=useApp();const [tab,setTab]=useState("all");const active=data.documents.filter(d=>!["archived","complete","approved","draft"].includes(d.status));const overdue=active.filter(d=>d.due&&d.due<today());const review=data.documents.filter(d=>d.status==="review");const completed=data.documents.filter(d=>["approved","complete","archived"].includes(d.status));const tasks=data.tasks.filter(t=>t.assignee===actor&&!taskClosed(t));const shown=tab==="mine"?active.filter(d=>actionable(d,actor)):tab==="review"?review:active;return <>
 <PageHead title="Рабочий стол" subtitle={new Date().toLocaleDateString("ru-RU",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).replace(/^./,x=>x.toUpperCase())}><button className="btn primary" onClick={()=>open({kind:"create"})}><Plus size={19}/>Создать документ<ChevronDown size={15}/></button></PageHead>
 <div className="stats-grid">{[{label:"Документы в работе",n:active.length,icon:Files,color:"blue",hint:"В активных процессах",view:"active"},{label:"На согласовании",n:review.length,icon:GitBranch,color:"purple",hint:"Ожидают решения",view:"review"},{label:"Просрочено",n:overdue.length,icon:Clock,color:"amber",hint:"Требуют вашего внимания",view:"overdue"},{label:"Завершено",n:completed.length,icon:FileCheck2,color:"teal",hint:"Утверждены и исполнены",view:"completed"}].map(s=><button key={s.label} className={`stat-card ${s.color}`} onClick={()=>go(s.view)}><span className="stat-heading">{s.label}<s.icon size={19}/></span><span className="stat-bottom"><b>{s.n.toString().padStart(2,"0")}</b><ArrowUpRight size={18}/></span><span className="stat-hint">{s.hint}</span></button>)}</div>
 <div className="dashboard-grid"><div className="dashboard-primary"><section className="panel attention-panel"><div className="panel-heading"><h2>В центре внимания <span className="count-label">{active.length}</span></h2><button className="text-button" onClick={()=>go("documents")}>Все документы<ArrowRight size={15}/></button></div><Tabs value={tab} onValueChange={setTab}><TabsList variant="line" className="line-tabs dashboard-tabs"><TabsTrigger value="all">Все события</TabsTrigger><TabsTrigger value="review">Согласование<span>{review.length}</span></TabsTrigger><TabsTrigger value="mine">Требуют меня<span>{active.filter(d=>actionable(d,actor)).length}</span></TabsTrigger></TabsList></Tabs><DocTable docs={shown.slice(0,5)} compact/><div className="panel-foot"><span>Показано {Math.min(5,shown.length)} из {shown.length} документов</span><button className="text-button" onClick={()=>go(tab==="review"?"review":"documents")}>Открыть реестр<ChevronRight size={15}/></button></div></section>
 <section className="panel activity-panel"><div className="panel-heading"><h2>Последние действия</h2><span className="muted text-small">Журнал событий</span></div><div className="activity-grid">{data.events.slice(0,3).map(e=><button key={e.id} className="activity-item" onClick={()=>e.documentId&&go("doc",e.documentId)}><Avatar id={e.actor}/><div><div className="activity-top"><b>{person(e.actor).name}</b><small>{new Date(e.createdAt).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}</small></div><p>{e.action}</p><span>{data.documents.find(d=>d.id===e.documentId)?.number||"Поручение"}<ArrowUpRight size={12}/></span></div></button>)}</div></section>
 <section className="panel my-tasks-panel"><div className="panel-heading"><h2>Мои поручения <span className="count-label">{tasks.length}</span></h2><button className="text-button" onClick={()=>go("tasks")}>Все поручения<ArrowRight size={15}/></button></div>{tasks.length?tasks.slice(0,2).map(t=><TaskRow key={t.id} task={t}/>):<div className="calm-empty"><CheckCheck size={18}/>Все поручения выполнены</div>}</section></div>
 <aside className="dashboard-aside"><CalendarPanel/><section className="panel quick-panel"><div className="panel-heading"><h2>Быстрые действия</h2></div><div className="quick-grid">{[{label:"Документ",sub:"Зарегистрировать",icon:FilePlus2,type:"create",color:"blue"},{label:"Договор",sub:"Подготовить",icon:BriefcaseBusiness,type:"contract",color:"purple"},{label:"Поручение",sub:"Назначить",icon:ClipboardCheck,type:"task",color:"teal"},{label:"Реестр",sub:"Все документы",icon:FolderOpen,type:"list",color:"amber"}].map(q=><button key={q.type} onClick={()=>q.type==="list"?go("documents"):open({kind:q.type==="task"?"task":"create",type:q.type==="contract"?"contract":undefined})}><span className={`quick-icon ${q.color}`}><q.icon size={20}/></span><b>{q.label}</b><small>{q.sub}</small></button>)}</div></section><div className="daily-note"><span className="daily-note-icon"><CheckCheck size={22}/></span><div><b>Всё под контролем</b><p>Решения, версии и комментарии сохраняются в карточке документа.</p></div></div></aside></div>
 </>}

function CalendarPanel(){const {data,go}=useApp();const [month,setMonth]=useState(()=>new Date(new Date().getFullYear(),new Date().getMonth(),1));const [selected,setSelected]=useState(today());const year=month.getFullYear(),m=month.getMonth(),offset=(new Date(year,m,1).getDay()+6)%7,days=new Date(year,m+1,0).getDate();const values=Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>new Date(year,m,i-offset+1));const key=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;const due=data.documents.filter(d=>d.due===selected&&!["archived","complete","approved"].includes(d.status));return <section className="panel calendar-panel"><div className="calendar-title"><h2>{month.toLocaleDateString("ru-RU",{month:"long",year:"numeric"}).replace(" г.","")}</h2><div><button aria-label="Предыдущий месяц" onClick={()=>setMonth(new Date(year,m-1,1))}><ChevronLeft size={17}/></button><button aria-label="Следующий месяц" onClick={()=>setMonth(new Date(year,m+1,1))}><ChevronRight size={17}/></button></div></div><div className="calendar-grid">{["Пн","Вт","Ср","Чт","Пт","Сб","Вс"].map(d=><span key={d} className="weekday">{d}</span>)}{values.map(d=><button key={key(d)} aria-label={dateText(key(d))} aria-pressed={selected===key(d)} onClick={()=>setSelected(key(d))} className={`${d.getMonth()!==m?"outside":""} ${key(d)===selected?"selected":""} ${key(d)===today()?"today":""}`}>{d.getDate()}{data.documents.some(x=>x.due===key(d)&&!["archived","complete","approved"].includes(x.status))&&<i/>}</button>)}</div><div className="calendar-agenda"><span>{selected===today()?"Сегодня":dateText(selected)}<small>Документов: {due.length}</small></span>{due.length?due.slice(0,2).map(d=><button key={d.id} onClick={()=>go("doc",d.id)}><i/><div><b>{d.title}</b><small>{d.number} · {statusLabels[d.status]}</small></div><ChevronRight size={14}/></button>):<p>На этот день сроков нет</p>}</div></section>}

function DocTable({docs,compact=false}:{docs:Doc[];compact?:boolean}){const {go}=useApp();if(!docs.length)return <Blank title="Документов нет" description="Попробуйте другой фильтр или создайте новый документ."/>;return <Table className={`documents-table ${compact?"compact":""}`}><TableHeader><TableRow><TableHead>Документ</TableHead><TableHead>Статус</TableHead>{!compact&&<TableHead>Участники</TableHead>}<TableHead>Срок</TableHead><TableHead><span className="sr-only">Открыть</span></TableHead></TableRow></TableHeader><TableBody>{docs.map(d=><TableRow key={d.id}><TableCell><div className="document-cell"><span className={`document-icon ${d.type}`}><FileText size={20}/></span><div><button className="document-title" onClick={()=>go("doc",d.id)}>{d.title}</button><p><span>{d.number}</span><span>·</span>{compact?docTypeName(d):d.correspondent||docTypeName(d)}</p></div></div></TableCell><TableCell><Status value={d.status}/></TableCell>{!compact&&<TableCell><div className="avatar-stack">{(d.approvers.length?d.approvers:[d.author]).slice(0,3).map(p=><Avatar key={p} id={p} small/>)}</div></TableCell>}<TableCell><div className={`due ${d.due&&d.due<today()&&!["archived","complete","approved"].includes(d.status)?"late":""}`}><span>{d.due===today()?"Сегодня":dateText(d.due)}</span>{d.due&&d.due<today()&&!["archived","complete","approved"].includes(d.status)&&<small>Просрочен</small>}</div></TableCell><TableCell><button className="row-open" aria-label={`Открыть ${d.number}`} onClick={()=>go("doc",d.id)}><ChevronRight size={17}/></button></TableCell></TableRow>)}</TableBody></Table>}

function DocumentsPage({view,search,setSearch}:{view:string;search:string;setSearch:(s:string)=>void}){const {data,open}=useApp();const [type,setType]=useState("all"),[status,setStatus]=useState("all"),[sort,setSort]=useState("new"),[page,setPage]=useState(1);useEffect(()=>{setPage(1);setType("all");setStatus("all");},[view]);useEffect(()=>setPage(1),[search,type,status]);let docs=data.documents.filter(d=>view==="active"?!["archived","complete","approved","draft"].includes(d.status):view==="completed"?["archived","complete","approved"].includes(d.status):view==="archive"?d.status==="archived":view==="contracts"?docFamily(d)==="contract"&&d.status!=="archived":["review","revision","approval"].includes(view)?d.status===view:view==="overdue"?d.due&&d.due<today()&&!["archived","approved","complete"].includes(d.status):d.status!=="archived").filter(d=>(type==="all"||d.type===type)&&(status==="all"||d.status===status)&&(!search||(d.title+" "+d.number+" "+d.correspondent+" "+d.description+" "+(d.externalNumber||"")+" "+(d.category||"")+" "+(d.tags||"")).toLowerCase().includes(search.toLowerCase())));docs.sort((a,b)=>sort==="due"?(a.due||"9999").localeCompare(b.due||"9999"):b.updatedAt.localeCompare(a.updatedAt));const totalPages=Math.max(1,Math.ceil(docs.length/8));const currentPage=Math.min(page,totalPages);function exportCsv(){const rows=[["Номер","Название","Тип","Контрагент","Статус","Срок"],...docs.map(d=>[d.number,d.title,docTypeName(d),d.correspondent,statusLabels[d.status],dateText(d.due)])];const safe=(v:string)=>/^[=+@\-]/.test(v)?"'"+v:v;const blob=new Blob(["\uFEFF"+rows.map(r=>r.map(x=>'"'+safe(x).replaceAll('"','""')+'"').join(";")).join("\r\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="RESMINAMA_documents.csv";a.click();URL.revokeObjectURL(url);}return <><PageHead title={search?"Результаты поиска":titles[view]||"Документы"} subtitle={`${docs.length} документов в реестре`}><button className="btn secondary" onClick={exportCsv}><Download size={17}/>Экспорт</button><button className="btn primary" onClick={()=>open({kind:"create",type:view==="contracts"?"contract":undefined})}><Plus size={18}/>Создать документ</button></PageHead><section className="panel"><div className="list-toolbar"><div className="local-search"><Search size={17}/><input aria-label="Поиск в реестре" placeholder="Название, номер или контрагент" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button aria-label="Очистить поиск" onClick={()=>setSearch("")}><X size={16}/></button>}</div><Pick label="Тип документа" value={type} onChange={setType} items={{all:"Все типы",...typeLabels}}/><Pick label="Статус" value={status} onChange={setStatus} items={{all:"Все статусы",...statusLabels}}/><button className="btn secondary sort-button" onClick={()=>setSort(sort==="new"?"due":"new")}><ArrowDownUp size={16}/>{sort==="new"?"Новые первыми":"По сроку"}</button></div><DocTable docs={docs.slice((currentPage-1)*8,currentPage*8)}/><div className="panel-foot"><span>{docs.length?`${(currentPage-1)*8+1}–${Math.min(currentPage*8,docs.length)} из ${docs.length}`:"Нет документов"}</span><Pagination className="table-pagination"><PaginationContent>{Array.from({length:totalPages},(_,i)=><PaginationItem key={i}><PaginationLink href="#" isActive={currentPage===i+1} onClick={e=>{e.preventDefault();setPage(i+1);}}>{i+1}</PaginationLink></PaginationItem>)}</PaginationContent></Pagination></div></section></>}

const taskLabels:Record<string,string>={new:"Новое",progress:"В работе",verification:"На приёмке",done:"Принято",cancelled:"Отменено"};
const taskClosed=(task:Task)=>["done","cancelled"].includes(task.status);
function TaskRow({task}:{task:Task}){const {data,open,go}=useApp();const doc=data.documents.find(d=>d.id===task.documentId);return <div className="task-row"><span className={`task-state ${task.status}`}><ClipboardCheck size={19}/></span><div className="task-content"><button className="task-title" onClick={()=>open({kind:"taskDetail",taskId:task.id})}>{task.title}</button><span>{doc&&<button onClick={()=>go("doc",doc.id)}>{doc.number}</button>}<span>{person(task.assignee).name}</span><span className={task.due&&task.due<today()&&!taskClosed(task)?"late":""}>{dateText(task.due)}</span></span></div><span className={`task-label ${task.status}`}>{taskLabels[task.status]}</span><button className="btn secondary small-btn" onClick={()=>open({kind:"taskDetail",taskId:task.id})}>Открыть</button></div>}
function TasksPage(){const {data,actor,open}=useApp();const [tab,setTab]=useState("mine");const tasks=data.tasks.filter(t=>tab==="all"?true:tab==="control"?t.controller===actor&&!taskClosed(t):tab==="done"?t.assignee===actor&&taskClosed(t):t.assignee===actor&&!taskClosed(t));return <><PageHead title="Поручения" subtitle="Исполнение, отчёты и приёмка результатов"><button className="btn primary" onClick={()=>open({kind:"task"})}><Plus size={18}/>Создать поручение</button></PageHead><section className="panel"><Tabs value={tab} onValueChange={setTab}><TabsList variant="line" className="line-tabs"><TabsTrigger value="mine">Мои активные</TabsTrigger><TabsTrigger value="control">На контроле</TabsTrigger><TabsTrigger value="done">Завершённые</TabsTrigger><TabsTrigger value="all">Все поручения</TabsTrigger></TabsList></Tabs>{tasks.length?tasks.map(t=><TaskRow key={t.id} task={t}/>):<Blank title="Нет поручений" description="Назначенные задачи появятся в этом разделе."/>}</section></>}

function ReadingsPage(){const {data,actor}=useApp();const mine=data.readings.filter(r=>r.recipients.includes(actor)||r.author===actor);return <><PageHead title="Ознакомление" subtitle="Документы для прочтения и подтверждения"/><UniversalReadings/><div className="readings-list">{mine.length?mine.map(r=><ReadingCard key={r.id} reading={r}/>):<section className="panel"><Blank title="Нет заданий на ознакомление" description="Отправьте документ на ознакомление из его карточки."/></section>}</div></>}
function ReadingCard({reading:r}:{reading:Reading}){const {data,actor,go,act,busy,open}=useApp();const d=data.documents.find(x=>x.id===r.documentId);return <section className="panel reading-card"><div className="reading-title"><span className="quick-icon blue"><Eye size={22}/></span><div><button onClick={()=>go("doc",r.documentId)}>{d?.title}</button><p>{d?.number} · Завершить к {dateText(r.due)}</p></div><span className="count-label">{r.done.length}/{r.recipients.length}</span></div>{r.comment&&<p className="reading-comment">{r.comment}</p>}<div className="reading-people">{r.recipients.map(p=><div key={p}><Avatar id={p} small/><span>{person(p).name}</span>{r.done.includes(p)?<span className="reading-done"><Check size={14}/>Ознакомлен</span>:<span className="muted">Ожидает</span>}</div>)}</div><div className="reading-actions">{d?.status!=="archived"&&(r.author===actor)&&<button className="btn secondary" onClick={()=>open({kind:"reading",documentId:r.documentId,readingId:r.id})}><Users size={16}/>Изменить участников</button>}{d?.status!=="archived"&&r.recipients.includes(actor)&&!r.done.includes(actor)&&<button disabled={busy} className="btn primary" onClick={()=>act("acknowledge",{readingId:r.id})}><CheckCheck size={17}/>Ознакомлен</button>}</div></section>}

function Directory(){const {data}=useApp();return <><PageHead title="Справочники" subtitle="Сотрудники, подразделения и контрагенты"/><Tabs defaultValue="people"><TabsList className="directory-tabs"><TabsTrigger value="people">Сотрудники</TabsTrigger><TabsTrigger value="departments">Подразделения</TabsTrigger><TabsTrigger value="partners">Контрагенты</TabsTrigger></TabsList><TabsContent value="people"><div className="people-grid">{people.map(p=><section className="panel person-card" key={p.id}><Avatar id={p.id}/><h2>{p.name}</h2><p>{p.role}{p.active===false?" · отключён":""}</p><span>{p.department}</span><div className="person-card-footer"><ClipboardCheck size={16}/>{data.tasks.filter(t=>t.assignee===p.id&&!taskClosed(t)).length} активных поручений</div></section>)}</div></TabsContent><TabsContent value="departments"><div className="people-grid">{people.map(p=><section className="panel person-card" key={p.id}><Building2 className="muted" size={28}/><h2>{p.department}</h2><p>{p.name}</p></section>)}</div></TabsContent><TabsContent value="partners"><section className="panel"><Table><TableHeader><TableRow><TableHead>Наименование</TableHead><TableHead>Документов</TableHead></TableRow></TableHeader><TableBody>{[...new Set(data.documents.filter(d=>["contract","incoming","outgoing"].includes(d.type)).map(d=>d.correspondent))].filter(Boolean).map(p=><TableRow key={p}><TableCell>{p}</TableCell><TableCell>{data.documents.filter(d=>d.correspondent===p).length}</TableCell></TableRow>)}</TableBody></Table></section></TabsContent></Tabs><p className="demo-caption">Состав сотрудников обновляется администратором в разделе «Пользователи». Отключённые учётные записи сохраняются в истории документов.</p></>}

function DocumentDetail({doc:d}:{doc:Doc}){const {data,actor,go,open,busy,act,upload,session}=useApp();const [tab,setTab]=useState(["review","approval"].includes(d.status)?"agreement":"details"),[comment,setComment]=useState(""),[versions,setVersions]=useState(false);const fileRef=useRef<HTMLInputElement>(null);const group=useRef<string|undefined>(undefined);const files=data.attachments.filter(f=>f.documentId===d.id);const displayed=versions?files:files.filter(f=>!files.some(o=>o.groupId===f.groupId&&o.version>f.version));const events=data.events.filter(e=>e.documentId===d.id);const readings=data.readings.filter(r=>r.documentId===d.id);const canManage=!!session?.canSwitch||d.author===actor;const canAssign=!currentStep(d)&&d.status!=="archived"&&(canManage||(d.editors||[]).includes(actor)||(d.iteration>0&&d.finalApprover===actor));const canEdit=(canManage||(d.editors||[]).includes(actor))&&["draft","revision"].includes(d.status);const canReview=!d.routePlan&&!d.process&&pendingFor(d,actor),canConfirm=!d.routePlan&&!d.process&&d.status==="approval"&&d.finalApprover===actor;
 return <><button className="back-link" onClick={()=>go("documents")}><ArrowLeft size={16}/>К документам</button><div className="document-heading"><div><div className="document-overline"><span>{docTypeName(d)}</span><span>№ {d.number}</span><span>от {dateText(d.date)}</span></div><h1>{d.title}</h1></div><DropdownMenu><DropdownMenuTrigger asChild><button className="btn secondary icon-only" aria-label="Действия с документом"><MoreHorizontal size={20}/></button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={()=>{location.href=`/api/card-docx?id=${encodeURIComponent(d.id)}`;}}><Download size={16}/>Карточка в DOCX</DropdownMenuItem><DropdownMenuItem onSelect={()=>window.print()}><Printer size={16}/>Печать карточки</DropdownMenuItem><DropdownMenuItem onSelect={async()=>{try{await navigator.clipboard.writeText(location.href);toast.success("Ссылка скопирована");}catch{toast.error("Не удалось скопировать ссылку");}}}><LinkIcon size={16}/>Скопировать ссылку</DropdownMenuItem></DropdownMenuContent></DropdownMenu></div>
 <div className="document-statusbar"><Status value={d.status}/><span><GitBranch size={15}/>{d.routePlan||d.process?"Маршрут · "+(currentStep(d)?.label||"Этапы документа"):"Согласование · "+(d.mode==="sequential"?"последовательное":"параллельное")}</span><span>Итерация {d.iteration||"—"}</span><span className="statusbar-date"><Clock size={15}/>Срок: {dateText(d.due)}</span></div>
 <div className={`detail-layout ${tab==="agreement"?"agreement-layout":""}`}><section className="panel detail-main">{(d.routePlan||d.process)&&tab!=="route"&&tab!=="agreement"&&<ProcessPanel key={`${d.id}:${actor}:${d.process?.id}:${d.process?.current}`} doc={d}/>}<Tabs value={tab} onValueChange={setTab}><TabsList variant="line" className="line-tabs detail-tabs"><TabsTrigger value="details">Реквизиты</TabsTrigger><TabsTrigger value="files">Вложения<span>{files.length}</span></TabsTrigger><TabsTrigger value="agreement">Согласование</TabsTrigger>{(d.routePlan||d.process)&&<TabsTrigger value="route">Маршрут</TabsTrigger>}<TabsTrigger value="readings">Ознакомление<span>{readings.length}</span></TabsTrigger><TabsTrigger value="access">Доступ</TabsTrigger><TabsTrigger value="history">Журнал</TabsTrigger><TabsTrigger value="discussion">Обсуждение<span>{events.filter(e=>e.kind==="comment").length}</span></TabsTrigger></TabsList>
 <TabsContent value="details"><div className="detail-padding"><div className="section-heading"><h2>Основная информация</h2>{canEdit&&<button className="text-button" onClick={()=>open({kind:"edit",documentId:d.id})}>Редактировать<ArrowUpRight size={15}/></button>}</div><dl className="details-grid"><div><dt>Регистрационный номер</dt><dd>{d.number}</dd></div><div><dt>Дата документа</dt><dd>{dateText(d.date)}</dd></div><div><dt>{docFamily(d)==="contract"?"Контрагент":"Отправитель / получатель"}</dt><dd>{d.correspondent||"Не указан"}</dd></div><div><dt>Подразделение</dt><dd>{d.department}</dd></div><div><dt>Автор документа</dt><dd className="person-value"><Avatar id={d.author} small/>{person(d.author).name}</dd></div><div><dt>Исполнить до</dt><dd className={d.due&&d.due<today()&&!['archived','complete','approved'].includes(d.status)?"late":""}>{dateText(d.due)}</dd></div>{docFamily(d)==="contract"&&<><div><dt>Сумма договора</dt><dd className="amount">{d.amount||"Не указана"} {d.amount&&d.currency}</dd></div><div><dt>Условия оплаты</dt><dd>{d.payment||"Не указаны"}</dd></div></>}</dl><CardDetails doc={d}/><ExtraFields doc={d}/><div className="description-block"><h3>Содержание документа</h3><p>{d.description||"Описание не заполнено."}</p></div>{d.status==="revision"&&<div className="revision-note"><RotateCcw size={19}/><div><b>Замечания к документу</b><p>{events.find(e=>e.action==="Возвращён на доработку")?.comment||"Уточните реквизиты и повторно запустите согласование."}</p></div></div>}<div className="section-heading lower-heading"><h2>Поручения по документу</h2>{canAssign&&d.status!=="archived"&&<button className="text-button" onClick={()=>open({kind:"task",documentId:d.id})}><Plus size={15}/>Добавить</button>}</div>{data.tasks.filter(t=>t.documentId===d.id).map(t=><TaskRow key={t.id} task={t}/>)}{!data.tasks.some(t=>t.documentId===d.id)&&<div className="calm-empty"><ClipboardCheck size={18}/>Поручения пока не назначены</div>}</div></TabsContent>
 <TabsContent value="files"><AttachmentsPanel doc={d} canEdit={canEdit}/></TabsContent>
 <TabsContent value="agreement"><ApprovalView key={`${d.id}:${actor}`} doc={d} onRoute={()=>setTab("route")}/></TabsContent>
 <TabsContent value="route">{(d.routePlan||d.process)&&<ProcessPanel key={`${d.id}:${actor}:${d.process?.id}:${d.process?.current}`} doc={d}/>}</TabsContent>
 <TabsContent value="readings"><div className="detail-padding"><div className="section-heading"><h2>Ознакомление сотрудников</h2>{canAssign&&<button className="btn secondary small-btn" onClick={()=>open({kind:"reading",documentId:d.id})}><Plus size={16}/>Отправить</button>}</div>{readings.length?readings.map(r=><ReadingCard reading={r} key={r.id}/>):<Blank title="Ознакомление не назначено" description="Выберите сотрудников, которым нужно прочитать документ."/>}</div></TabsContent>
 <TabsContent value="access"><AccessPanel doc={d}/></TabsContent>
 <TabsContent value="history"><div className="detail-padding"><div className="section-heading"><h2>Журнал действий</h2><span>{events.length} событий</span></div><EventGrid events={events}/></div></TabsContent>
 <TabsContent value="discussion"><div className="detail-padding"><h2>Обсуждение документа</h2><div className="history-list">{events.filter(e=>e.kind==="comment").slice().reverse().map(e=><div className="history-item" key={e.id}><Avatar id={e.actor}/><div><b>{person(e.actor).name}</b><span>{dateText(e.createdAt)}</span><p>{e.comment}</p></div></div>)}</div>{d.status!=="archived"&&<form className="comment-form" onSubmit={async e=>{e.preventDefault();if(await act("comment",{documentId:d.id,comment}))setComment("");}}><label htmlFor="comment-text">Новый комментарий</label><textarea id="comment-text" placeholder="Напишите сообщение участникам…" required value={comment} maxLength={3000} onChange={e=>setComment(e.target.value)}/><button className="btn primary" disabled={busy||!comment.trim()}><Send size={16}/>Отправить</button></form>}</div></TabsContent>
 </Tabs></section><aside className="detail-aside"><section className="panel actions-panel"><h2>Действия</h2>{canEdit&&!d.routePlan&&!d.process&&<><button className="btn primary" onClick={()=>open({kind:"submit",documentId:d.id})}><Send size={17}/>{d.status==="revision"?"Повторное согласование":"На согласование"}</button><button className="btn secondary" onClick={()=>open({kind:"edit",documentId:d.id})}><FileText size={17}/>Редактировать</button></>}{canReview&&<><button className="btn success" onClick={()=>open({kind:"approve",documentId:d.id})}><Check size={17}/>Согласовать</button><button className="btn danger-soft" onClick={()=>open({kind:"reject",documentId:d.id})}><RotateCcw size={17}/>На доработку</button></>}{canConfirm&&<><button className="btn success" onClick={()=>open({kind:"confirm",documentId:d.id})}><Stamp size={17}/>Утвердить</button><button className="btn danger-soft" onClick={()=>open({kind:"reject",documentId:d.id})}><RotateCcw size={17}/>На доработку</button></>}{!canEdit&&!canReview&&!canConfirm&&<p className="action-hint">{d.status==="archived"?"Документ передан в архив.":d.status==="review"?"Ожидается решение назначенных согласующих.":d.status==="approval"?`Ожидается решение: ${person(d.finalApprover).name}.`:"Основной этап обработки завершён."}</p>}{!d.process&&["review","approval"].includes(d.status)&&canManage&&<button className="btn secondary" onClick={()=>open({kind:"participants",documentId:d.id})}><Users size={17}/>Изменить участников</button>}<div className="action-divider"/>{canManage&&["approved","complete"].includes(d.status)&&<button className="btn secondary" onClick={()=>open({kind:"reopen",documentId:d.id})}><RotateCcw size={17}/>Открыть доработку</button>}{canAssign&&<button className="btn secondary" onClick={()=>open({kind:"reading",documentId:d.id})}><Eye size={17}/>На ознакомление</button>}{canAssign&&d.status!=="archived"&&<button className="btn secondary" onClick={()=>open({kind:"task",documentId:d.id})}><ClipboardCheck size={17}/>Поручение / резолюция</button>}{["complete","approved"].includes(d.status)&&(session?.canSwitch||session?.systemRole==="archivist"||[d.author,d.finalApprover].includes(actor))&&<button className="btn secondary" disabled={busy} onClick={()=>open({kind:"archive",documentId:d.id})}><Archive size={17}/>Передать в архив</button>}{!d.process&&d.author===actor&&["review","approval"].includes(d.status)&&<button className="text-button cancel-route" onClick={()=>open({kind:"cancel",documentId:d.id})}>Отменить процесс</button>}</section>{d.status==="archived"&&(session?.canSwitch||session?.systemRole==="archivist")&&<section className="panel actions-panel"><button className="btn secondary" onClick={()=>open({kind:"restore",documentId:d.id})}><RotateCcw size={17}/>Вернуть из архива</button></section>}<section className="panel participants-panel"><h2>Участники</h2>{[...new Set([d.author,...d.approvers,d.finalApprover])].map(id=><div className="participant" key={id}><Avatar id={id} small/><div><b>{person(id).name}</b><small>{id===d.author?"Инициатор":id===d.finalApprover?"Утверждающий":"Согласующий"}</small></div>{d.approvals[id]==="approved"&&<Check className="teal-text" size={16}/>}</div>)}</section><p className="detail-meta">Создан {dateText(d.createdAt)}<br/>Изменён {dateText(d.updatedAt)}</p></aside></div></>;
}

function ModalFlow({modal,close}:{modal:Modal;close:()=>void}){const {data,actor,busy,act,go,session}=useApp();const [templateId,setTemplateId]=useState("custom");const [related,setRelated]=useState<string[]>(data.documents.find(x=>x.id===modal.documentId)?.relatedIds||[]);const [assignees,setAssignees]=useState<string[]>([]);const [controller,setController]=useState(actor);const d=data.documents.find(d=>d.id===modal.documentId);const reading=data.readings.find(r=>r.id===modal.readingId);const [fields,setFields]=useState<Record<string,string>>({title:d?.title||"",type:modal.type||d?.type||"incoming",correspondent:d?.correspondent||"",department:d?.department||person(actor).department,description:d?.description||"",amount:d?.amount||"",currency:d?.currency||"TMT",payment:d?.payment||"",date:d?.date||today(),due:reading?.due||d?.due||"",externalNumber:d?.externalNumber||"",externalDate:d?.externalDate||"",registeredAt:d?.registeredAt||today(),category:d?.category||"",tags:d?.tags||"",priority:d?.priority||"normal",caseId:d?.caseId||data.cases?.find(c=>!c.closed)?.id||"general"});const [comment,setComment]=useState(""),[selected,setSelected]=useState<string[]>(reading?.recipients||d?.approvers.length&&d.approvers||["legal","finance","it"]),[mode,setMode]=useState(d?.mode||"parallel"),[finalApprover,setFinal]=useState(d?.finalApprover||"director"),[onlyPending,setOnlyPending]=useState(false),[assignee,setAssignee]=useState("it"),[linked,setLinked]=useState(modal.documentId||"none");
 const names:Record<string,string>={create:"Новый документ",edit:"Редактирование документа",submit:"Отправить на согласование",participants:"Изменить участников согласования",approve:"Согласовать документ",reject:"Вернуть на доработку",confirm:"Утвердить документ",reopen:"Открыть доработку",reading:reading?"Изменить участников ознакомления":"Отправить на ознакомление",task:"Новое поручение",help:"Добро пожаловать в RESMINAMA"};
 const field=(name:string,label:string,type="text",required=false)=> <label className="form-field">{label}{required&&<span className="required">*</span>}<input type={type} required={required} value={fields[name]} maxLength={name==="description"?3000:200} onChange={e=>setFields({...fields,[name]:e.target.value})}/></label>;
 async function submit(e:React.FormEvent){e.preventDefault();let result:SedState|null=null;if(["create","edit"].includes(modal.kind)){result=await act(modal.kind,{documentId:d?.id,payload:{...fields,relatedIds:related}});if(result&&modal.kind==="create")go("doc",result.documents[0].id);}else if(["submit","participants"].includes(modal.kind)){result=await act(modal.kind,{documentId:d?.id,approvers:selected,mode,finalApprover,comment,onlyPending});}else if(modal.kind==="reading"){result=await act("reading",{documentId:d?.id,readingId:reading?.id,recipients:selected,due:fields.due,comment});}else if(modal.kind==="task"){result=await act("createTask",{documentId:linked==="none"?undefined:linked,title:fields.title,assignees,controller,due:fields.due});}else result=await act(modal.kind,{documentId:d?.id,comment});if(result)close();}
 if(modal.kind==="cancel")return <AlertDialog open onOpenChange={v=>!v&&close()}><AlertDialogContent><AlertDialogTitle>Отменить согласование?</AlertDialogTitle><AlertDialogDescription>Документ вернётся в черновики. Текущие решения будут сброшены, история останется в журнале.</AlertDialogDescription><AlertDialogFooter><AlertDialogCancel>Назад</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={async e=>{e.preventDefault();if(await act("cancel",{documentId:d?.id}))close();}}>Отменить процесс</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>;
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className={`app-dialog ${["create","edit","submit","participants","reading"].includes(modal.kind)?"wide-dialog":""}`}><DialogHeader><DialogTitle>{names[modal.kind]}</DialogTitle><DialogDescription>{modal.kind==="help"?"Демонстрационная система электронного документооборота":d?`${d.number} · ${d.title}`:modal.kind==="create"?"Заполните реквизиты. Номер будет присвоен автоматически.":"Укажите исполнителя и срок."}</DialogDescription></DialogHeader>{modal.kind==="help"?<><div className="help-steps"><div><span>1</span><div><b>Подготовьте документ</b><p>Создайте карточку, заполните реквизиты и добавьте вложения.</p></div></div><div><span>2</span><div><b>Запустите согласование</b><p>Выберите сотрудников и порядок. Для проверки решений переключайте участника в меню профиля.</p></div></div><div><span>3</span><div><b>Утвердите и передайте на исполнение</b><p>Директор утверждает документ. Назначьте поручения, отправьте на ознакомление и завершите работу в архиве.</p></div></div></div><div className="info-note"><AlertCircle size={19}/><p>Данные хранятся локально на компьютере сервера. Начальные сотрудники и документы демонстрационные. Каждый сотрудник входит под своей учётной записью; только администратор может переключать роли для проверки. DOCX создаётся по шаблону; редактируйте скачанную копию в Word или ONLYOFFICE Desktop и загружайте новую версию. ЭЦП и почтовая отправка не подключены.</p></div><DialogFooter><button className="btn primary" onClick={close}>Начать работу<ArrowRight size={16}/></button></DialogFooter></>:<form onSubmit={submit} className="modal-form">
 {["create","edit"].includes(modal.kind)&&<><div className="form-grid"><label className="form-field">Тип документа{modal.kind==="edit"?<span className="readonly-type">{typeLabels[fields.type]}</span>:<Pick label="Тип нового документа" value={fields.type} onChange={v=>setFields({...fields,type:v})} items={typeLabels}/>}</label>{field("date","Дата документа","date",true)}</div>{field("title","Название документа","text",true)}<div className="form-grid">{field("correspondent",fields.type==="contract"?"Контрагент":"Отправитель / получатель")}{field("department","Подразделение")}</div><label className="form-field">Содержание<textarea value={fields.description} maxLength={3000} rows={3} onChange={e=>setFields({...fields,description:e.target.value})} placeholder="Краткое содержание и основание документа"/></label><div className="form-grid">{field("due","Исполнить до","date")}{fields.type==="contract"&&<div className="amount-field">{field("amount","Сумма")}<label className="form-field">Валюта<Pick label="Валюта" value={fields.currency} onChange={v=>setFields({...fields,currency:v})} items={{TMT:"TMT",USD:"USD",RUB:"RUB"}}/></label></div>}</div>{fields.type==="contract"&&field("payment","Условия оплаты")}<div className="form-grid">{field("registeredAt","Дата регистрации","date",true)}<label className="form-field">Приоритет<Pick label="Приоритет документа" value={fields.priority} onChange={priority=>setFields({...fields,priority})} items={{normal:"Обычный",high:"Высокий",urgent:"Срочный"}}/></label>{field("externalNumber","Внешний номер")}{field("externalDate","Дата внешнего документа","date")}{field("category","Категория")}{field("tags","Метки через запятую")}</div><label className="form-field">Дело<Pick label="Дело документа" value={fields.caseId} onChange={caseId=>setFields({...fields,caseId})} items={Object.fromEntries((data.cases||[]).filter(c=>!c.closed).map(c=>[c.id,c.index+" · "+c.title]))}/></label><label className="form-field">Связанные документы<select multiple value={related} onChange={e=>setRelated(Array.from(e.target.selectedOptions,o=>o.value))} className="linked-select">{data.documents.filter(x=>x.id!==d?.id).map(x=><option key={x.id} value={x.id}>{x.number} · {x.title}</option>)}</select><small className="muted">Ctrl + щелчок — выбрать или снять несколько связей.</small></label></>}
 {modal.kind==="submit"&&<label className="form-field">Шаблон маршрута<Pick label="Шаблон маршрута" value={templateId} items={{custom:"Настроить вручную",...Object.fromEntries((data.templates||[]).map(t=>[t.id,t.name]))}} onChange={id=>{setTemplateId(id);const t=data.templates?.find(t=>t.id===id);if(t){setSelected(t.approvers);setMode(t.mode);setFinal(t.finalApprover);}}}/><small className="muted">Участников выбранного шаблона можно изменить перед отправкой.</small></label>}
 {["submit","participants","reading"].includes(modal.kind)&&<>{["submit","participants"].includes(modal.kind)&&<div className="form-grid"><label className="form-field">Порядок согласования<Pick value={mode} onChange={setMode} label="Порядок согласования" items={{parallel:"Параллельно",sequential:"Последовательно"}}/></label><label className="form-field">Утверждающий<Pick value={finalApprover} onChange={setFinal} label="Утверждающий" items={roleItems()}/></label></div>}<div className="form-label">{modal.kind!=="reading"?"Согласующие":"Ознакомляющиеся"}<span className="required">*</span><span className="muted">Выбрано: {selected.length}</span></div><div className="people-picker">{people.filter(p=>p.active!==false||selected.includes(p.id)).map(p=><label className={selected.includes(p.id)?"selected":""} key={p.id}><Checkbox checked={selected.includes(p.id)} onCheckedChange={v=>setSelected(v?[...selected,p.id]:selected.filter(x=>x!==p.id))}/><Avatar id={p.id} small/><span><b>{p.name}</b><small>{p.department}{p.active===false?" · отключён — удалите из выбора":""}</small></span>{mode==="sequential"&&["submit","participants"].includes(modal.kind)&&selected.includes(p.id)&&<em>{selected.indexOf(p.id)+1}</em>}</label>)}</div>{mode==="sequential"&&["submit","participants"].includes(modal.kind)&&<p className="muted text-small">Очередь задаётся порядком выбора сотрудников.</p>}{modal.kind==="reading"&&field("due","Ознакомиться до","date")}{modal.kind==="submit"&&d?.status==="revision"&&<label className="checkbox-label"><Checkbox checked={onlyPending} onCheckedChange={v=>setOnlyPending(v===true)}/>Повторно согласовать только у не согласовавших</label>}</>}
 {modal.kind==="task"&&<>{field("title","Поручение / текст резолюции","text",true)}<label className="form-field">Связанный документ<Pick label="Связанный документ" value={linked} onChange={setLinked} items={{none:"Без документа",...Object.fromEntries(data.documents.filter(d=>d.status!=="archived"&&(session?.canSwitch||d.author===actor||(d.iteration>0&&d.finalApprover===actor)||(d.editors||[]).includes(actor))).map(d=>[d.id,`${d.number} · ${d.title}`]))}}/></label><div className="form-label">Исполнители · {assignees.length}</div><PeopleSelector selected={assignees} onChange={setAssignees}/><label className="form-field">Контролёр<Pick label="Контролёр поручения" value={controller} onChange={setController} items={roleItems()}/></label><p className="muted text-small">Каждый исполнитель получит отдельное поручение. Контролёр принимает отчёт или возвращает его на доработку.</p>{field("due","Исполнить до","date")}</>}
 {!["create","edit","task"].includes(modal.kind)&&<label className="form-field">{modal.kind==="reject"||modal.kind==="reopen"?"Причина доработки":"Комментарий"}{(modal.kind==="reject"||modal.kind==="reopen"||modal.kind==="participants"||!!reading)&&<span className="required">*</span>}<textarea required={modal.kind==="reject"||modal.kind==="reopen"||modal.kind==="participants"||!!reading} value={comment} maxLength={3000} onChange={e=>setComment(e.target.value)} rows={3} placeholder={modal.kind==="reject"?"Что необходимо исправить?":"Комментарий участникам процесса"}/></label>}
 {modal.kind==="confirm"&&<p className="info-note">Утверждение фиксирует решение руководителя. Электронная подпись не создаётся.</p>}
 <DialogFooter><button type="button" className="btn secondary" onClick={close}>Отмена</button><button disabled={busy||(modal.kind==="task"&&!assignees.length)||(["submit","participants","reading"].includes(modal.kind)&&!selected.length)} type="submit" className={`btn ${modal.kind==="reject"?"danger":"primary"}`}>{busy?<Loader2 size={17} className="animate-spin"/>:<Check size={17}/>}{{create:"Создать документ",edit:"Сохранить",submit:"Отправить",participants:"Сохранить участников",approve:"Согласовать",reject:"Вернуть на доработку",confirm:"Утвердить",reopen:"Открыть доработку",reading:reading?"Сохранить участников":"Отправить",task:"Назначить поручение"}[modal.kind]}</button></DialogFooter></form>}</DialogContent></Dialog>
}

export function PeopleSelector({selected,onChange,disabled=false}:{selected:string[];onChange:(v:string[])=>void;disabled?:boolean}){
 return <div className="people-picker">{people.filter(p=>p.active!==false||selected.includes(p.id)).map(p=><label key={p.id} className={selected.includes(p.id)?"selected":""}><Checkbox disabled={disabled} checked={selected.includes(p.id)} onCheckedChange={v=>onChange(v?[...selected,p.id]:selected.filter(x=>x!==p.id))}/><Avatar id={p.id} small/><span><b>{p.name}</b><small>{p.department}{p.active===false?" · отключён":""}</small></span>{selected.includes(p.id)&&<em>{selected.indexOf(p.id)+1}</em>}</label>)}</div>;
}

function AccessPanel({doc}:{doc:Doc}){
 const {actor,session,act,busy}=useApp();
 const allowed=doc.status!=="archived"&&(doc.author===actor||!!session?.canSwitch);
 const [isPublic,setPublic]=useState(!!doc.isPublic),[access,setAccess]=useState(doc.access||[]),[editors,setEditors]=useState(doc.editors||[]);
 useEffect(()=>{setPublic(!!doc.isPublic);setAccess(doc.access||[]);setEditors(doc.editors||[]);},[doc]);
 return <div className="detail-padding"><div className="section-heading"><h2>Доступ к документу</h2><span className="count-label">{doc.isPublic?"Всем сотрудникам":"Ограниченный"}</span></div>
 <p className="access-explanation">Автор, редакторы, назначенные участники согласования, инициаторы, контролёры и исполнители поручений, а также получатели ознакомления имеют доступ автоматически. Администратор видит все документы.</p>
 <form className="modal-form" onSubmit={async e=>{e.preventDefault();await act("access",{documentId:doc.id,isPublic,access,editors});}}>
 <label className="checkbox-label"><Checkbox checked={isPublic} disabled={!allowed} onCheckedChange={v=>setPublic(v===true)}/>Доступен всем сотрудникам организации</label>
 {!isPublic&&<><div className="form-label">Дополнительный доступ для просмотра</div><PeopleSelector selected={access} onChange={setAccess} disabled={!allowed}/><p className="muted text-small">Просмотр позволяет скачать вложения и участвовать в обсуждении. Редактирование реквизитов и решения по маршруту доступны только назначенным участникам.</p></>}
 <div className="form-label">Редакторы реквизитов и вложений</div><PeopleSelector selected={editors} onChange={setEditors} disabled={!allowed}/><p className="muted text-small">Редакторы работают с черновиком и доработкой, запускают согласование и назначают поручения. Управление доступом остаётся у автора и администратора.</p>
 {allowed&&<button disabled={busy} className="btn primary fit-button"><Check size={17}/>Сохранить доступ</button>}
 </form><h3 className="access-heading">Автоматический доступ</h3><div className="access-members">{(doc.automaticAccess||[doc.author]).map(id=><span key={id}><Avatar id={id} small/>{person(id).name}</span>)}</div>
 {!allowed&&<p className="muted text-small">Настройки доступа изменяет автор документа или администратор.</p>}</div>;
}

function UsersPage(){
 const {session,data,act,busy}=useApp();
 const [query,setQuery]=useState(""),[editor,setEditor]=useState<Person|"new"|null>(null);
 const [command,setCommand]=useState<{person:Person;action:"userReset"|"userActive"}|null>(null);
 if(!session?.canSwitch)return <Blank title="Раздел администратора" description="Управление сотрудниками доступно администратору системы."/>;
 const list=people.filter(p=>(p.name+" "+p.id+" "+p.department).toLowerCase().includes(query.toLowerCase()));
 const auditLabels:Record<string,string>={userCreate:"Создание пользователя",userEdit:"Изменение профиля",userReset:"Сброс пароля",caseSave:"Изменение дела",userActive:"Изменение состояния",documentTypeSave:"Тип документа",processTemplateSave:"Шаблон процесса"};
 return <><PageHead title="Пользователи" subtitle="Учётные записи, подразделения и права администратора"><button className="btn primary" onClick={()=>setEditor("new")}><Plus size={18}/>Добавить сотрудника</button></PageHead>
 <section className="panel management-panel"><div className="management-toolbar"><Search size={18}/><input aria-label="Найти сотрудника" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Имя, логин или подразделение…"/><span>{list.length} сотрудников</span></div>
 <Table><TableHeader><TableRow><TableHead>Сотрудник</TableHead><TableHead>Подразделение / должность</TableHead><TableHead>Права</TableHead><TableHead>Статус</TableHead><TableHead>Действия</TableHead></TableRow></TableHeader><TableBody>{list.map(p=><TableRow key={p.id}><TableCell><div className="user-cell"><Avatar id={p.id}/><div><b>{p.name}</b><small>{p.id}</small></div></div></TableCell><TableCell>{p.department||"—"}<small className="table-subline">{p.role}</small></TableCell><TableCell>{p.systemRole==="admin"?"Администратор":p.systemRole==="archivist"?"Архивариус":"Сотрудник"}</TableCell><TableCell><span className={`status ${p.active===false?"draft":"approved"}`}><span/>{p.active===false?"Отключён":"Активен"}</span></TableCell><TableCell><DropdownMenu><DropdownMenuTrigger asChild><button className="icon-button" aria-label={`Действия: ${p.name}`}><MoreHorizontal size={20}/></button></DropdownMenuTrigger><DropdownMenuContent align="end"><DropdownMenuItem onSelect={()=>setEditor(p)}>Редактировать профиль</DropdownMenuItem><DropdownMenuItem onSelect={()=>setCommand({person:p,action:"userReset"})}>Сбросить пароль</DropdownMenuItem>{p.id!==session.username&&<DropdownMenuItem onSelect={()=>setCommand({person:p,action:"userActive"})}>{p.active===false?"Включить учётную запись":"Отключить учётную запись"}</DropdownMenuItem>}</DropdownMenuContent></DropdownMenu></TableCell></TableRow>)}</TableBody></Table>{!list.length&&<Blank title="Сотрудники не найдены" description="Измените поисковый запрос."/>}</section>
 <p className="demo-caption">Отключённые сотрудники остаются в истории. Система не позволит отключить учётную запись с незавершёнными документами, поручениями или ознакомлениями.</p>
 <section className="panel management-panel audit-panel"><div className="section-heading"><h2>Журнал администрирования</h2></div>{data.adminAudit?.length?<Table><TableHeader><TableRow><TableHead>Дата</TableHead><TableHead>Действие</TableHead><TableHead>Пользователь</TableHead><TableHead>Администратор</TableHead></TableRow></TableHeader><TableBody>{data.adminAudit.slice(0,30).map(a=><TableRow key={a.id}><TableCell>{dateText(a.createdAt)} · {new Date(a.createdAt).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}</TableCell><TableCell>{auditLabels[a.action]||a.action}</TableCell><TableCell>{person(a.target).name}</TableCell><TableCell>{person(a.actor).name}</TableCell></TableRow>)}</TableBody></Table>:<p className="muted">Изменения пользователей будут записаны здесь.</p>}</section>
 {editor&&<UserEditor key={typeof editor==="string"?editor:editor.id} user={editor==="new"?undefined:editor} close={()=>setEditor(null)}/>}
 {command&&<AlertDialog open onOpenChange={v=>!v&&setCommand(null)}><AlertDialogContent><AlertDialogTitle>{command.action==="userReset"?"Сбросить пароль?":command.person.active===false?"Включить пользователя?":"Отключить пользователя?"}</AlertDialogTitle><AlertDialogDescription>{command.person.name}. {command.action==="userReset"?"Будет создан новый случайный пароль. Все текущие сеансы пользователя завершатся.":command.person.active===false?"Сотрудник сможет войти с текущим паролем.":"Сеансы завершатся. Документы и история сотрудника сохранятся."}</AlertDialogDescription><AlertDialogFooter><AlertDialogCancel>Отмена</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={async e=>{e.preventDefault();if(await act(command.action,{username:command.person.id,active:command.person.active===false}))setCommand(null);}}>Подтвердить</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>}
 </>;
}

function UserEditor({user,close}:{user?:Person;close:()=>void}){
 const {act,busy,session}=useApp();
 const [fields,setFields]=useState({username:user?.id||"",name:user?.name||"",department:user?.department||"",title:user?.role||"",role:user?.systemRole||"employee"});
 const field=(name:"username"|"name"|"department"|"title",label:string,required=false)=><label className="form-field">{label}{required&&<span className="required">*</span>}<input required={required} disabled={name==="username"&&!!user} autoComplete="off" maxLength={name==="username"?40:100} pattern={name==="username"?"[a-z][a-z0-9_.-]{2,39}":undefined} value={fields[name]} onChange={e=>setFields({...fields,[name]:e.target.value})}/></label>;
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className="app-dialog"><DialogHeader><DialogTitle>{user?"Профиль сотрудника":"Новый сотрудник"}</DialogTitle><DialogDescription>{user?"Логин сохраняется, чтобы не нарушить историю документов.":"После создания система покажет первоначальный пароль."}</DialogDescription></DialogHeader><form className="modal-form" onSubmit={async e=>{e.preventDefault();if(await act(user?"userEdit":"userCreate",fields))close();}}>{field("username","Логин (латиница, 3–40 символов)",true)}{field("name","Имя и фамилия",true)}{field("department","Подразделение")}{field("title","Должность")}<label className="form-field">Права в системе{user?.id===session?.username?<span className="readonly-type">Администратор</span>:<Pick label="Права пользователя" value={fields.role} items={{employee:"Сотрудник",archivist:"Архивариус",admin:"Администратор"}} onChange={role=>setFields({...fields,role})}/>}</label>{fields.role==="archivist"&&<p className="info-note">Архивариус видит все архивные документы, ведёт дела и оформляет возврат документов из архива.</p>}{fields.role==="admin"&&<p className="info-note">Администратор видит все документы, управляет пользователями и может выполнять действия от имени сотрудников.</p>}<DialogFooter><button type="button" className="btn secondary" onClick={close}>Отмена</button><button disabled={busy} className="btn primary">{user?"Сохранить":"Создать пользователя"}</button></DialogFooter></form></DialogContent></Dialog>;
}

function TemplatesPage(){
 const {data,session,act,busy}=useApp();const [editor,setEditor]=useState<RouteTemplate|"new"|null>(null),[remove,setRemove]=useState<RouteTemplate|null>(null);
 return <><PageHead title="Шаблоны маршрутов" subtitle="Сохранённые участники и порядок согласования"><button className="btn primary" onClick={()=>setEditor("new")}><Plus size={18}/>Создать шаблон</button></PageHead>
 <div className="template-grid">{(data.templates||[]).map(t=><section key={t.id} className="panel template-card"><div className="template-heading"><span className="quick-icon blue"><GitBranch size={22}/></span><div><h2>{t.name}</h2><p>{t.mode==="sequential"?"Последовательно":"Параллельно"} · {t.approvers.length} согласующих</p></div></div><ol className="template-route">{t.approvers.map(id=><li key={id}><Avatar id={id} small/><span>{person(id).name}{person(id).active===false&&<small className="late">Отключён — измените шаблон</small>}</span></li>)}</ol><div className="template-final"><Stamp size={18}/><span>Утверждает <b>{person(t.finalApprover).name}</b>{person(t.finalApprover).active===false&&<small className="late">Отключён — измените шаблон</small>}</span></div><div className="template-footer"><small>Автор: {person(t.owner).name}</small>{(session?.canSwitch||session?.username===t.owner)&&<div><button className="text-button" onClick={()=>setEditor(t)}>Изменить</button><button className="text-button danger-text" onClick={()=>setRemove(t)}>Удалить</button></div>}</div></section>)}</div>
 {!data.templates?.length&&<section className="panel"><Blank title="Сохраните первый маршрут" description="Добавьте согласующих и утверждающего. Затем выбирайте этот шаблон при отправке документа."/></section>}
 <p className="demo-caption">Шаблоны доступны всем сотрудникам. Изменять шаблон может его автор или администратор. Изменение шаблона не меняет уже запущенные маршруты.</p>
 {editor&&<TemplateEditor key={typeof editor==="string"?editor:editor.id} template={editor==="new"?undefined:editor} close={()=>setEditor(null)}/>}
 {remove&&<AlertDialog open onOpenChange={v=>!v&&setRemove(null)}><AlertDialogContent><AlertDialogTitle>Удалить шаблон «{remove.name}»?</AlertDialogTitle><AlertDialogDescription>Уже запущенные согласования сохранят своих участников.</AlertDialogDescription><AlertDialogFooter><AlertDialogCancel>Отмена</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={async e=>{e.preventDefault();if(await act("templateDelete",{templateId:remove.id}))setRemove(null);}}>Удалить шаблон</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>}
 </>;
}

function TemplateEditor({template,close}:{template?:RouteTemplate;close:()=>void}){
 const {act,busy}=useApp();const [name,setName]=useState(template?.name||""),[selected,setSelected]=useState(template?.approvers||[]),[mode,setMode]=useState(template?.mode||"parallel"),[finalApprover,setFinal]=useState(template?.finalApprover||"director");
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className="app-dialog wide-dialog"><DialogHeader><DialogTitle>{template?"Изменить шаблон":"Новый шаблон маршрута"}</DialogTitle><DialogDescription>Маршрут можно использовать для документов любого типа.</DialogDescription></DialogHeader><form className="modal-form" onSubmit={async e=>{e.preventDefault();if(await act("templateSave",{templateId:template?.id,name,approvers:selected,mode,finalApprover}))close();}}><label className="form-field">Название<span className="required">*</span><input required maxLength={120} value={name} onChange={e=>setName(e.target.value)} placeholder="Например, согласование договора"/></label><div className="form-grid"><label className="form-field">Порядок согласования<Pick label="Порядок шаблона" value={mode} onChange={setMode} items={{parallel:"Параллельно",sequential:"Последовательно"}}/></label><label className="form-field">Утверждающий<Pick label="Утверждающий шаблона" value={finalApprover} onChange={setFinal} items={roleItems()}/></label></div><div className="form-label">Согласующие · {selected.length}</div><PeopleSelector selected={selected} onChange={setSelected}/>{mode==="sequential"&&<p className="muted text-small">Этапы идут в порядке выбора сотрудников. Чтобы поменять позицию, снимите отметку и выберите сотрудника снова.</p>}<DialogFooter><button type="button" className="btn secondary" onClick={close}>Отмена</button><button className="btn primary" disabled={busy||!selected.length}>Сохранить шаблон</button></DialogFooter></form></DialogContent></Dialog>;
}

function CardDetails({doc:d}:{doc:Doc}){
 const {data,go}=useApp();const c=data.cases?.find(c=>c.id===d.caseId);
 return <><dl className="details-grid extended-fields"><div><dt>Дата регистрации</dt><dd>{dateText(d.registeredAt||"")}</dd></div><div><dt>Приоритет</dt><dd>{{normal:"Обычный",high:"Высокий",urgent:"Срочный"}[d.priority||"normal"]}</dd></div><div><dt>Внешний документ</dt><dd>{d.externalNumber||"—"} · {dateText(d.externalDate||"")}</dd></div><div><dt>Категория и метки</dt><dd>{[d.category,d.tags].filter(Boolean).join(" · ")||"Не указаны"}</dd></div><div><dt>Дело</dt><dd>{c?c.index+" · "+c.title:"Не выбрано"}</dd></div><div><dt>Редакторы</dt><dd>{d.editors?.map(id=>person(id).name).join(", ")||"Автор и администратор"}</dd></div></dl>
 {!!d.relatedIds?.length&&<div className="related-documents"><h3>Связанные документы</h3>{d.relatedIds.map(id=>{const doc=data.documents.find(x=>x.id===id);return doc&&<button className="text-button" key={id} onClick={()=>go("doc",id)}><LinkIcon size={15}/>{doc.number} · {doc.title}</button>})}</div>}
 {d.archive&&<div className="archive-summary"><h3>Архивная запись</h3><p>Передан {dateText(d.archive.date)} · Дело {d.archive.caseIndex} · {d.archive.caseTitle}</p><p>Срок хранения: {d.archive.years===null?"Не установлен при переносе":d.archive.years===0?"Постоянно":d.archive.years+" лет"}. {d.archive.reviewAfter&&`Пересмотр не ранее ${dateText(d.archive.reviewAfter)}.`}</p>{d.archive.location&&<p>Место хранения: {d.archive.location}</p>}<small>Документ доступен только для чтения. Истечение срока не удаляет его автоматически.</small></div>}</>;
}

function TaskDialog({taskId,close}:{taskId:string;close:()=>void}){
 const {data,actor,session,act,busy,go}=useApp();const t=data.tasks.find(t=>t.id===taskId);
 const [report,setReport]=useState(""),[comment,setComment]=useState(""),[edit,setEdit]=useState(false),[assignee,setAssignee]=useState(t?.assignee||actor),[controller,setController]=useState(t?.controller||actor),[due,setDue]=useState(t?.due||"");
 if(!t)return null;const manager=!!session?.canSwitch||[t.author,t.controller].includes(actor);const doc=data.documents.find(d=>d.id===t.documentId);
 const doAction=async(action:string,p:Record<string,unknown>={})=>{if(await act(action,{taskId:t.id,comment,...p})){setComment("");setReport("");setEdit(false);}};
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className="app-dialog wide-dialog"><DialogHeader><DialogTitle>{t.title}</DialogTitle><DialogDescription>{taskLabels[t.status]} · Срок {dateText(t.due)}</DialogDescription></DialogHeader><div className="task-dialog-content"><dl className="details-grid"><div><dt>Исполнитель</dt><dd>{person(t.assignee).name}</dd></div><div><dt>Контролёр</dt><dd>{person(t.controller||t.author||"").name}</dd></div><div><dt>Инициатор</dt><dd>{person(t.author||"").name}</dd></div><div><dt>Документ</dt><dd>{doc?<button className="text-button" onClick={()=>{close();go("doc",doc.id);}}>{doc.number}</button>:"Без документа"}</dd></div></dl>
 {!!t.reports?.length&&<div className="task-reports"><h3>Отчёты и решения</h3>{t.reports.map(r=><article key={r.id}><b>{person(r.actor).name}</b><small>{dateText(r.createdAt)}{r.decision==="taskReturn"?" · Возвращено":r.decision==="taskAccept"?" · Принято":" · Отчёт"}</small><p>{r.text||"Исполнение отмечено в версии 0.2"}</p></article>)}</div>}
 {t.cancelReason&&<p className="revision-note">Причина отмены: {t.cancelReason}</p>}
 {actor===t.assignee&&t.status==="new"&&<button className="btn primary" disabled={busy} onClick={()=>doAction("taskStatus",{status:"progress"})}>Взять в работу</button>}
 {actor===t.assignee&&t.status==="progress"&&<form className="modal-form" onSubmit={e=>{e.preventDefault();doAction("taskStatus",{status:"verification",report});}}><label className="form-field">Отчёт об исполнении<textarea rows={4} required={t.requiresAcceptance} maxLength={3000} value={report} onChange={e=>setReport(e.target.value)} placeholder="Что выполнено, какой получен результат?"/></label><button className="btn primary fit-button" disabled={busy}>{t.requiresAcceptance?"Передать на приёмку":"Завершить поручение"}</button></form>}
 {manager&&!taskClosed(t)&&<div className="task-control"><h3>Контроль исполнения</h3><label className="form-field">Комментарий или причина<textarea value={comment} onChange={e=>setComment(e.target.value)} maxLength={3000} rows={2} placeholder="Для возврата, переназначения и отмены причина обязательна"/></label>{t.status==="verification"&&<div className="inline-actions"><button className="btn success" disabled={busy} onClick={()=>doAction("taskAccept")}>Принять исполнение</button><button className="btn danger-soft" disabled={busy||!comment.trim()} onClick={()=>doAction("taskReturn")}>Вернуть на доработку</button></div>}<div className="inline-actions"><button className="btn secondary" onClick={()=>setEdit(!edit)}>Исполнитель и срок</button><button className="text-button danger-text" disabled={busy||!comment.trim()} onClick={()=>doAction("taskCancel")}>Отменить поручение</button></div>{edit&&<div className="modal-form"><label className="form-field">Исполнитель<Pick label="Новый исполнитель" value={assignee} onChange={setAssignee} items={roleItems()}/></label><label className="form-field">Контролёр<Pick label="Новый контролёр" value={controller} onChange={setController} items={roleItems()}/></label><label className="form-field">Срок<input type="date" value={due} onChange={e=>setDue(e.target.value)}/></label><button className="btn primary fit-button" disabled={busy||!comment.trim()} onClick={()=>doAction("taskEdit",{assignee,controller,due})}>Сохранить изменения</button></div>}</div>}
 </div><DialogFooter><button className="btn secondary" onClick={close}>Закрыть</button></DialogFooter></DialogContent></Dialog>;
}

function ArchiveDialog({modal,close}:{modal:Modal;close:()=>void}){
 const {data,act,busy,go}=useApp();const doc=data.documents.find(d=>d.id===modal.documentId);
 const [caseId,setCase]=useState(doc?.caseId||"general"),[location,setLocation]=useState(""),[comment,setComment]=useState("");
 if(!doc)return null;const c=data.cases?.find(c=>c.id===caseId);
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className="app-dialog"><DialogHeader><DialogTitle>{modal.kind==="archive"?"Передать документ в архив":"Возврат из архива"}</DialogTitle><DialogDescription>{doc.number} · {doc.title}</DialogDescription></DialogHeader><form className="modal-form" onSubmit={async e=>{e.preventDefault();const result=await act(modal.kind,{documentId:doc.id,caseId,location,comment});if(result){close();if(!result.documents.some(x=>x.id===doc.id))go("archive");}}}>{modal.kind==="archive"?<><label className="form-field">Архивное дело<Pick label="Архивное дело" value={caseId} onChange={setCase} items={Object.fromEntries((data.cases||[]).filter(c=>!c.closed).map(c=>[c.id,c.index+" · "+c.title]))}/></label><p className="muted">Срок по делу: {c?.years===0?"постоянно":`${c?.years||0} лет`}. Настройка срока должна соответствовать правилам вашей организации.</p><label className="form-field">Место хранения оригинала<input maxLength={200} value={location} onChange={e=>setLocation(e.target.value)} placeholder="Например, шкаф 2, полка 3"/></label><p className="info-note">Передача заблокирует изменения карточки и вложений. Все поручения и ознакомления должны быть завершены.</p></>:<label className="form-field">Причина возврата<textarea required maxLength={3000} rows={4} value={comment} onChange={e=>setComment(e.target.value)}/></label>}<DialogFooter><button type="button" className="btn secondary" onClick={close}>Отмена</button><button className="btn primary" disabled={busy}>{modal.kind==="archive"?"Передать в архив":"Вернуть из архива"}</button></DialogFooter></form></DialogContent></Dialog>;
}

function ArchivePage(){
 const {data,go}=useApp();const [query,setQuery]=useState(""),[caseId,setCase]=useState("all"),[year,setYear]=useState("all"),[due,setDue]=useState(false);
 const archived=data.documents.filter(d=>d.status==="archived");const years=[...new Set(archived.map(d=>d.archive?.date.slice(0,4)||d.updatedAt.slice(0,4)))].sort().reverse();
 const docs=archived.filter(d=>(caseId==="all"||d.archive?.caseId===caseId)&&(year==="all"||(d.archive?.date||d.updatedAt).startsWith(year))&&(!due||!!d.archive?.reviewAfter&&d.archive.reviewAfter<=today())&&(d.title+" "+d.number+" "+(d.archive?.location||"")).toLowerCase().includes(query.toLowerCase()));
 function exportInventory(){const rows=[["Номер","Название","Дело","Дата архива","Хранение лет","Пересмотр после","Место оригинала"],...docs.map(d=>[d.number,d.title,d.archive?.caseIndex||"",d.archive?.date||"",d.archive?.years===null?"Не установлен":d.archive?.years===0?"Постоянно":String(d.archive?.years??""),d.archive?.reviewAfter||"",d.archive?.location||""])];const csv="\uFEFF"+rows.map(row=>row.map(v=>'"'+(/^[=+@\-]/.test(v)?"'":"")+v.replaceAll('"','""')+'"').join(";")).join("\r\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="RESMINAMA_archive_inventory.csv";a.click();URL.revokeObjectURL(url);}
 return <><PageHead title="Архив документов" subtitle={`${docs.length} документов · сохранение версий и истории`}><button className="btn secondary" onClick={exportInventory}><Download size={17}/>Опись CSV</button><button className="btn secondary" onClick={()=>go("cases")}><FolderOpen size={17}/>Дела и сроки</button></PageHead><section className="panel"><div className="list-toolbar"><div className="local-search"><Search size={17}/><input aria-label="Поиск в архиве" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Номер, название, место хранения"/></div><Pick label="Дело в архиве" value={caseId} onChange={setCase} items={{all:"Все дела",...Object.fromEntries((data.cases||[]).map(c=>[c.id,c.index+" · "+c.title]))}}/><Pick label="Год архива" value={year} onChange={setYear} items={{all:"Все годы",...Object.fromEntries(years.map(y=>[y,y]))}}/></div><label className="checkbox-label archive-filter"><Checkbox checked={due} onCheckedChange={v=>setDue(v===true)}/>Подошёл срок пересмотра хранения</label><Table><TableHeader><TableRow><TableHead>Документ</TableHead><TableHead>Дело</TableHead><TableHead>Передан в архив</TableHead><TableHead>Хранение</TableHead><TableHead>Место оригинала</TableHead></TableRow></TableHeader><TableBody>{docs.map(d=><TableRow key={d.id}><TableCell><button className="document-title" onClick={()=>go("doc",d.id)}>{d.title}</button><small className="table-subline">{d.number}</small></TableCell><TableCell>{d.archive?.caseIndex||"—"}</TableCell><TableCell>{dateText(d.archive?.date||"")}</TableCell><TableCell>{d.archive?.years===null?"Не установлен":d.archive?.years===0?"Постоянно":`${d.archive?.years||0} лет`}<small className="table-subline">{d.archive?.reviewAfter?"Пересмотр: "+dateText(d.archive.reviewAfter):""}</small></TableCell><TableCell>{d.archive?.location||"—"}</TableCell></TableRow>)}</TableBody></Table>{!docs.length&&<Blank title="Архивных документов нет" description="После завершения работы передайте документ в архив из карточки."/>}</section><p className="demo-caption">Срок хранения задаётся в деле. Дата пересмотра отсчитывается с 1 января следующего года. Автоматическое уничтожение документов не выполняется.</p></>;
}

function CasesPage(){
 const {data,session}=useApp();const canManage=session?.canSwitch||session?.systemRole==="archivist";const [edit,setEdit]=useState<CaseFile|"new"|null>(null);
 return <><PageHead title="Дела и сроки хранения" subtitle="Индексы дел и правила хранения документов">{canManage&&<button className="btn primary" onClick={()=>setEdit("new")}><Plus size={17}/>Создать дело</button>}</PageHead><section className="panel"><Table><TableHeader><TableRow><TableHead>Индекс</TableHead><TableHead>Название</TableHead><TableHead>Хранение</TableHead><TableHead>Статус</TableHead><TableHead>Документов</TableHead><TableHead/></TableRow></TableHeader><TableBody>{(data.cases||[]).map(c=><TableRow key={c.id}><TableCell>{c.index}</TableCell><TableCell>{c.title}</TableCell><TableCell>{c.years===0?"Постоянно":c.years+" лет"}</TableCell><TableCell>{c.closed?"Закрыто":"Открыто"}</TableCell><TableCell>{data.documents.filter(d=>d.caseId===c.id).length}</TableCell><TableCell>{canManage&&<button className="text-button" onClick={()=>setEdit(c)}>Изменить</button>}</TableCell></TableRow>)}</TableBody></Table></section><p className="demo-caption">Изменение срока в деле применяется к следующим передачам в архив. Уже сохранённые архивные записи остаются неизменными. Сроки утверждает ваша организация.</p>{edit&&<CaseEditor key={typeof edit==="string"?edit:edit.id} value={edit==="new"?undefined:edit} close={()=>setEdit(null)}/>}</>;
}
function CaseEditor({value,close}:{value?:CaseFile;close:()=>void}){
 const {act,busy}=useApp();const [index,setIndex]=useState(value?.index||""),[title,setTitle]=useState(value?.title||""),[years,setYears]=useState(String(value?.years??5)),[closed,setClosed]=useState(!!value?.closed);
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className="app-dialog"><DialogHeader><DialogTitle>{value?"Изменить дело":"Новое дело"}</DialogTitle><DialogDescription>Закрытое дело нельзя выбрать для новых документов.</DialogDescription></DialogHeader><form className="modal-form" onSubmit={async e=>{e.preventDefault();if(await act("caseSave",{caseId:value?.id,index,title,years:Number(years),closed}))close();}}><label className="form-field">Индекс<input required maxLength={50} value={index} onChange={e=>setIndex(e.target.value)}/></label><label className="form-field">Название<input required maxLength={150} value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="form-field">Срок хранения в годах (0 — постоянно)<input type="number" required min={0} max={100} step={1} value={years} onChange={e=>setYears(e.target.value)}/></label><label className="checkbox-label"><Checkbox checked={closed} onCheckedChange={v=>setClosed(v===true)}/>Закрыть дело для новых документов</label><DialogFooter><button type="button" className="btn secondary" onClick={close}>Отмена</button><button className="btn primary" disabled={busy}>Сохранить дело</button></DialogFooter></form></DialogContent></Dialog>;
}

function AttachmentsPanel({doc,canEdit}:{doc:Doc;canEdit:boolean}){
 const {data,session,act,upload,busy}=useApp();const [versions,setVersions]=useState(false),[template,setTemplate]=useState("memo"),[preview,setPreview]=useState<{name:string;paragraphs:string[];notice:string;truncated:boolean}|null>(null),[loading,setLoading]=useState(false);
 const fileInput=useRef<HTMLInputElement>(null),group=useRef<string|undefined>(undefined);const files=data.attachments.filter(f=>f.documentId===doc.id);const shown=versions?files:files.filter(f=>!files.some(x=>x.groupId===f.groupId&&x.version>f.version));
 async function showPreview(id:string,name:string){setLoading(true);try{const r=await fetch('/api/docx-preview?id='+encodeURIComponent(id));const body=await r.json();if(!r.ok)throw new Error(body.error);setPreview({name,...body});}catch(e){toast.error(e instanceof Error?e.message:"Не удалось открыть DOCX");}finally{setLoading(false);}}
 return <div className="detail-padding"><div className="section-heading"><h2>Файлы и версии</h2>{canEdit&&<button className="btn primary small-btn" disabled={busy} onClick={()=>{group.current=undefined;fileInput.current?.click();}}><Upload size={16}/>Добавить файл</button>}</div><input ref={fileInput} type="file" hidden accept=".docx,.doc,.pdf,.xlsx,.xls,.txt,.png,.jpg,.jpeg,.sig,.p7s,.cms" onChange={e=>{const file=e.target.files?.[0];if(file)upload(file,doc.id,group.current);e.target.value="";}}/>
 {canEdit&&<div className="docx-create"><Pick label="Шаблон DOCX" value={template} onChange={setTemplate} items={Object.fromEntries((data.docxTemplates||[]).map(t=>[t.id,t.name]))}/><button className="btn secondary" disabled={busy} onClick={()=>act("generateDocx",{documentId:doc.id,templateId:template})}><FilePlus2 size={17}/>Создать DOCX</button></div>}
 <label className="checkbox-label version-toggle"><Checkbox checked={versions} onCheckedChange={v=>setVersions(v===true)}/>Показать предыдущие версии</label>
 {shown.length?<div className="attachment-cards">{shown.map(f=>{const lease=data.fileLocks?.find(l=>l.groupId===f.groupId);const latest=!files.some(x=>x.groupId===f.groupId&&x.version>f.version);const owned=lease?.username===session?.username;return <article className="attachment-card" key={f.id}><div className="file-name"><FileText size={24}/><div><b>{f.name}</b><small>v{f.version} · {Math.max(1,Math.round(f.size/1024))} КБ · {person(f.author).name} · {dateText(f.createdAt)}</small></div></div>{lease&&latest&&<p className="file-lease">Редактирует {person(lease.actor).name} · блокировка до {new Date(lease.expires*1000).toLocaleString("ru-RU")}</p>}<div className="inline-actions"><a className="btn secondary small-btn" href={'/api/files?id='+encodeURIComponent(f.id)}><Download size={15}/>Скачать</a>{f.name.toLowerCase().endsWith('.docx')&&<button className="btn secondary small-btn" disabled={loading} onClick={()=>showPreview(f.id,f.name)}><Eye size={15}/>Текст DOCX</button>}{canEdit&&latest&&<><button className="btn secondary small-btn" disabled={busy||!!lease&&!owned} onClick={async()=>{if(await act("fileCheckout",{documentId:doc.id,fileId:f.id})){const a=document.createElement('a');a.href='/api/files?id='+encodeURIComponent(f.id);a.click();}}}>Взять на редактирование</button><button className="btn secondary small-btn" disabled={busy||!!lease&&!owned} onClick={()=>{group.current=f.groupId;fileInput.current?.click();}}>Загрузить версию</button>{lease&&(owned||session?.canSwitch)&&<button className="text-button" disabled={busy} onClick={()=>{const comment=owned?"Отмена редактирования":window.prompt("Причина снятия блокировки:")||"";if(owned||comment.trim())act("fileRelease",{documentId:doc.id,fileId:f.id,comment});}}>Снять блокировку</button>}</>}</div></article>})}</div>:<Blank title="Файлов пока нет" description="Добавьте вложение или создайте DOCX из реквизитов карточки."/>}
 <p className="info-note">Для работы в Word или ONLYOFFICE Desktop возьмите файл на редактирование, измените скачанную копию и загрузите новую версию. Блокировка действует 24 часа; согласование запускается после её снятия. Старые версии сохраняются.</p>
 {preview&&<Dialog open onOpenChange={v=>!v&&setPreview(null)}><DialogContent className="app-dialog wide-dialog"><DialogHeader><DialogTitle>{preview.name}</DialogTitle><DialogDescription>{preview.notice}</DialogDescription></DialogHeader><div className="docx-text-preview">{preview.paragraphs.map((p,i)=><p key={i}>{p}</p>)}{preview.truncated&&<p className="late">Текст сокращён. Скачайте файл для полного просмотра.</p>}</div><DialogFooter><button className="btn secondary" onClick={()=>setPreview(null)}>Закрыть</button></DialogFooter></DialogContent></Dialog>}
 </div>;
}
